import { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import api from "../api";

function Profile() {
  const { userId: paramUserId } = useParams();
  const navigate = useNavigate();

  // 🔐 AUTH
  const storedUserId = localStorage.getItem("userId");
  const loggedInUserId = storedUserId ? Number(storedUserId) : null;

  // 👤 WHOSE PROFILE
  const profileUserId = paramUserId
    ? Number(paramUserId)
    : loggedInUserId;

  const isOwnProfile = profileUserId === loggedInUserId;

  const [loading, setLoading] = useState(true);
  const [role, setRole] = useState("");
  const [editMode, setEditMode] = useState(false);

  const [profile, setProfile] = useState({
    full_name: "",
    email: "",
    phone: "",
    batch: "",
    company: "",
    designation: "",
    profile_image: null,
  });

  // ✅ ADDED
  const [preview, setPreview] = useState(null);
  const [imageFile, setImageFile] = useState(null);

  /* 🔐 HARD GUARD */
  useEffect(() => {
    if (!loggedInUserId) {
      navigate("/login");
    }
  }, [loggedInUserId, navigate]);

  /* 📡 FETCH PROFILE */
  useEffect(() => {
    if (!profileUserId) return;

    setLoading(true);

    api
      .get(`/profile/${profileUserId}`)
      .then((res) => {
        setRole(res.data.role);
        setProfile({
          full_name: res.data.full_name || "",
          email: res.data.email || "",
          phone: res.data.phone || "",
          batch: res.data.batch || "",
          company: res.data.company || "",
          designation: res.data.designation || "",
          profile_image: res.data.profile_image || null,
        });
      })
      .catch(() => {
        alert("Profile not found");
        navigate("/feed");
      })
      .finally(() => setLoading(false));
  }, [profileUserId, navigate]);

  if (loading) {
    return (
      <div className="profile-page">
        <div className="profile-card glass">
          <p>Loading profile...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="profile-page">
      <div className="profile-card glass">
        <h2>{isOwnProfile ? "My Profile" : "Profile"}</h2>

        {/* ✅ FIXED AVATAR */}
        <div className="profile-avatar-lg">
          {preview ? (
            <img src={preview} alt="profile" />
          ) : profile.profile_image ? (
            <img
              src={`http://localhost:5000${profile.profile_image}`}
              alt="profile"
            />
          ) : (
            <svg viewBox="0 0 24 24">
              <circle cx="12" cy="8" r="4" />
              <path d="M4 20c0-4 4-6 8-6s8 2 8 6" />
            </svg>
          )}
        </div>

        {/* ✅ ADD IMAGE PICKER ONLY IN EDIT MODE */}
        {editMode && isOwnProfile && (
          <label className="change-photo">
            Change photo
            <input
              type="file"
              hidden
              accept="image/*"
              onChange={(e) => {
                const file = e.target.files[0];
                setImageFile(file);
                setPreview(URL.createObjectURL(file));
              }}
            />
          </label>
        )}

        {/* VIEW MODE */}
        {!editMode && (
          <div className="profile-info">
            <p><strong>Name:</strong> {profile.full_name}</p>
            <p><strong>Email:</strong> {profile.email}</p>

            {isOwnProfile && (
              <p><strong>Phone:</strong> {profile.phone}</p>
            )}

            <p><strong>Batch:</strong> {profile.batch}</p>

            {role === "ALUMNI" && (
              <>
                <p><strong>Company:</strong> {profile.company}</p>
                <p><strong>Designation:</strong> {profile.designation}</p>
              </>
            )}

            {isOwnProfile && (
              <button
                className="edit-btn"
                onClick={() => setEditMode(true)}
              >
                Edit Profile
              </button>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

export default Profile;
